/**
 * External secret managers: shared fetch logic for HashiCorp Vault, AWS Secrets Manager and
 * Azure Key Vault, used by bruno-electron and bruno-cli.
 *
 * `getExternalSecretsData` is the unified entry point. Callers pass only data: the provider
 * `config`, the secret `paths`, and a `networkConfig` (the same proxy/TLS config shape consumed
 * by `getHttpHttpsAgents`). Agent resolution happens here — no `resolveAgents` callback crosses
 * the package boundary.
 */

import { fetchHashicorpVaultSecrets } from './hashicorp-vault';
import { fetchAwsSecretsManagerSecrets } from './aws-secrets-manager';
import { fetchAzureKeyVaultSecrets } from './azure-key-vault';
import { fetchGcpSecretsManagerSecrets } from './gcp-secrets-manager';
import type { VaultPathResult } from './hashicorp-vault';
import type { SecretManagerNetworkConfig } from './resolve-agents';

export * from './resolve-agents';
export * from './hashicorp-vault';
export * from './aws-secrets-manager';
export * from './azure-key-vault';
export * from './gcp-secrets-manager';

export type ExternalSecretType = 'vault' | 'aws-secrets-manager' | 'azure-key-vault' | 'gcp-secrets-manager';

export interface ExternalSecretResult {
  path: string;
  data?: any;
  error?: any;
}

// Fetch external secrets for a single provider. Callers pass only the provider `config`, the
// secret `paths`, and a `networkConfig` (proxy/TLS) — agent resolution stays internal. `debug`
// (optional) is forwarded to the Vault client for verbose logging.
export const getExternalSecretsData = async ({
  type,
  config,
  paths,
  networkConfig,
  debug
}: {
  type: ExternalSecretType;
  config: any;
  paths: string[];
  networkConfig?: SecretManagerNetworkConfig;
  debug?: (...args: any[]) => void;
}): Promise<ExternalSecretResult[] | VaultPathResult[] | undefined> => {
  if (type === 'vault') {
    return fetchHashicorpVaultSecrets({ config, paths, networkConfig, debug });
  }

  if (type === 'aws-secrets-manager') {
    const results = await fetchAwsSecretsManagerSecrets({
      awsConfig: config?.awsConfig || {},
      secretNames: paths,
      networkConfig
    });
    return results.map((r) => ({ path: r.secretName, data: r.data, error: r.error }));
  }

  if (type === 'azure-key-vault') {
    // No azure provider config (no/other --secrets-env-file) → fall back to the Azure CLI credential.
    const results = await fetchAzureKeyVaultSecrets({
      azureConfig: config?.azureConfig || {},
      vaultNames: paths,
      networkConfig,
      useCLI: !config?.azureConfig
    });
    return results.map((r) => ({ path: r.vaultName, data: r.data, error: r.error }));
  }

  if (type === 'gcp-secrets-manager') {
    // GCP's `paths` are project ids; each result's `data` holds every secret in that project, keyed
    // by secret id.
    const results = await fetchGcpSecretsManagerSecrets({
      gcpConfig: config?.gcpConfig || {},
      projectIds: paths,
      networkConfig
    });
    return results.map((r) => ({ path: r.projectId, data: r.data, error: r.error }));
  }

  return undefined;
};
